const money = (n?: number | null) => n == null ? '—' : n >= 1000000 ? `R$ ${(n / 1000000).toFixed(1).replace('.', ',')} mi` : `R$ ${Math.round(n / 1000)} mil`;
const fullMoney = (n?: number | null) => n == null ? '—' : `R$ ${n.toLocaleString('pt-BR', { minimumFractionDigits: 0 })}`;
const shortDate = (d?: string | null) => d ? new Date(d).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' }).replace('.', '') : 'Sem data';
const initials = (value = 'Corretor') => value.split(' ').slice(0, 2).map((x) => x[0]).join('').toUpperCase();

