          <div className="mt-4 flex items-center gap-2 rounded-xl bg-sidebar-accent/60 p-2.5"><div className="flex size-8 items-center justify-center rounded-full bg-sidebar-primary font-mono-ui text-xs text-sidebar-primary-foreground">{initials(user?.firstName || 'MB')}</div><div className="min-w-0"><div className="truncate text-xs font-medium text-sidebar-accent-foreground">{user?.firstName || 'Marina Barros'}</div><div className="truncate text-[10px] text-sidebar-foreground/50">Corretora solo</div></div><MoreHorizontal size={15} className="ml-auto text-sidebar-foreground/45" /></div>
