function PropertyCard({ property }: { property: any }) { return <Link href={`/properties/${property.id}`} data-testid={`card-property-${property.id}`} className="group overflow-hidden rounded-xl border border-border bg-card shadow-xs transition hover:-translate-y-1 hover:shadow-md"><div className="relative h-44 overflow-hidden bg-muted">{property.image ? <img src={property.image} alt={property.title} className="size-full object-cover transition duration-500 group-hover:scale-105" /> : <div className="flex size-full items-center justify-center bg-[#dfe4df] text-primary/40"><Building2 size={32} /></div>}<div className="absolute left-3 top-3"><Status tone={property.exclusive ? 'warm' : 'neutral'}>{property.exclusive ? 'Exclusivo' : property.status || 'Disponível'}</Status></div><div className="absolute bottom-3 right-3 rounded bg-primary/85 px-2 py-1 font-mono-ui text-[9px] text-primary-foreground">{property.code}</div></div><div className="p-4"><div className="font-display text-lg font-semibold">{property.title}</div><div className="mt-1 text-xs text-muted-foreground">{property.neighborhood}, {property.city}</div><div className="mt-4 flex items-end justify-between"><div><div className="font-display text-xl font-semibold">{money(property.price)}</div><div className="mt-1 text-xs text-muted-foreground">{property.bedrooms} quartos · {property.area} m²</div></div><ChevronRight size={17} className="text-muted-foreground transition group-hover:translate-x-1" /></div></div></Link>; }
function PropertyDetail() { const { id } = useParams<{ id: string }>(); const propertyId = Number(id); const { data: property, isLoading } = useGetProperty(propertyId, { query: { enabled: !!propertyId, queryKey: getGetPropertyQueryKey(propertyId) } }); const update = useUpdateProperty(); if (isLoading) return <Panel><LoadingRows count={5} /></Panel>; if (!property) return <Empty label="Imóvel não encontrado." />; return <><Link href="/properties" className="mb-5 inline-flex items-center gap-1 text-xs font-semibold text-muted-foreground">← Voltar para imóveis</Link><div className="grid gap-5 xl:grid-cols-[1.3fr_.7fr]"><div><Panel className="overflow-hidden"><div className="relative h-72 bg-muted md:h-96">{property.image ? <img src={property.image} alt={property.title} className="size-full object-cover" /> : <div className="flex size-full items-center justify-center bg-[#dfe4df] text-primary/35"><Building2 size={45} /></div>}<div className="absolute bottom-4 left-5"><Status tone="warm">{property.exclusive ? 'Exclusivo' : property.status}</Status></div></div><div className="p-6"><div className="font-mono-ui text-[10px] uppercase tracking-[.15em] text-muted-foreground">{property.code} · {property.type}</div><h2 className="mt-2 font-display text-3xl font-semibold tracking-tight">{property.title}</h2><p className="mt-2 text-sm text-muted-foreground">{property.address || property.neighborhood}, {property.city}</p><div className="mt-6 grid grid-cols-2 gap-y-5 sm:grid-cols-4"><DetailLine label="Preço" value={money(property.price)} /><DetailLine label="Área" value={`${property.area} m²`} /><DetailLine label="Quartos" value={String(property.bedrooms)} /><DetailLine label="Vagas" value={String(property.parking)} /></div>{property.description && <p className="mt-6 border-t border-border pt-5 text-sm leading-relaxed text-muted-foreground">{property.description}</p>}</div></Panel><Panel className="mt-5 p-5"><div className="flex items-center justify-between"><div><h3 className="font-display text-lg font-semibold">Clientes compatíveis</h3><p className="mt-1 text-xs text-muted-foreground">Quem já procura algo parecido</p></div><Users size={18} className="text-[#317e77]" /></div><div className="mt-4 grid gap-2 sm:grid-cols-2">{(property.recommendations || []).slice(0, 4).map((client) => <Link href={`/clients/${client.id}`} key={client.id} className="flex items-center gap-3 rounded-lg border border-border p-3 hover:bg-muted/35"><Avatar name={client.name} tone="teal" /><div className="min-w-0 flex-1"><div className="truncate text-sm font-semibold">{client.name}</div><div className="text-xs text-muted-foreground">{client.interest}</div></div><span className="font-mono-ui text-xs text-[#317e77]">{client.matchScore ?? 84}%</span></Link>)}{!property.recommendations?.length && <Empty label="Clientes compatíveis aparecerão aqui." />}</div></Panel></div><aside><Panel className="p-5"><div className="flex items-start justify-between"><div><div className="font-mono-ui text-[9px] uppercase tracking-wider text-muted-foreground">Valor do imóvel</div><div className="mt-2 font-display text-3xl font-semibold">{fullMoney(property.price)}</div></div><div className="rounded-lg bg-accent/25 p-2 text-[#9b681d]"><TrendingUp size={18} /></div></div><div className="mt-5 grid gap-3"><button data-testid="button-property-share" onClick={() => toast.success('Link copiado para compartilhar.')} className="w-full rounded-lg bg-primary py-2.5 text-xs font-semibold text-primary-foreground">Compartilhar imóvel</button><button data-testid="button-property-status" onClick={() => update.mutate({ id: property.id, data: { status: property.status === 'vendido' ? 'disponível' : 'vendido' } }, { onSuccess: () => toast.success('Status atualizado.') })} className="w-full rounded-lg border border-border py-2.5 text-xs font-semibold">Atualizar status</button></div></Panel><Panel className="mt-5 p-5"><h3 className="font-display text-lg font-semibold">Detalhes financeiros</h3><div className="mt-5 grid gap-4"><DetailLine label="Proprietário" value={property.ownerName} /><DetailLine label="Comissão" value={`${property.commission}%`} /><DetailLine label="Condomínio" value={fullMoney(property.condo)} /><DetailLine label="IPTU" value={fullMoney(property.iptu)} /></div></Panel></aside></div></>; }

function Tasks() { const [filter, setFilter] = useState<any>('all'); const [showAdd, setShowAdd] = useState(false); const { data, isLoading } = useListTasks({ filter }); const create = useCreateTask(); const update = useUpdateTask(); const qc = useQueryClient(); const submit = (e: React.FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); create.mutate({ data: { title: String(f.get('title')), type: 'follow-up', date: String(f.get('date')), time: String(f.get('time') || ''), priority: String(f.get('priority')), clientName: String(f.get('clientName') || '') } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListTasksQueryKey() }); setShowAdd(false); toast.success('Tarefa criada.'); } }); }; return <><PageHeader title="Tarefas" description="Um lugar para o que precisa acontecer depois." action={() => setShowAdd(true)} actionLabel="Nova tarefa" /><div className="mb-5 flex gap-1 overflow-x-auto rounded-lg border border-border bg-card p-1">{['all','today','overdue','tomorrow','week','completed'].map((f) => <button data-testid={`button-filter-task-${f}`} key={f} onClick={() => setFilter(f)} className={`whitespace-nowrap rounded-md px-3 py-2 text-xs font-semibold transition ${filter === f ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-muted'}`}>{f === 'all' ? 'Todas' : f === 'today' ? 'Hoje' : f === 'overdue' ? 'Vencidas' : f === 'tomorrow' ? 'Amanhã' : f === 'week' ? 'Esta semana' : 'Concluídas'}</button>)}</div><Panel>{isLoading ? <LoadingRows /> : !data?.length ? <Empty label="Nenhuma tarefa nesta visão." action={() => setShowAdd(true)} /> : <div className="divide-y divide-border">{data.map((task) => <div key={task.id} className="flex items-center gap-3 px-5 py-4 transition hover:bg-muted/35"><button data-testid={`button-complete-task-${task.id}`} onClick={() => update.mutate({ id: task.id, data: { status: task.status === 'completed' ? 'open' : 'completed' } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListTasksQueryKey({ filter }) }); toast.success('Tarefa atualizada.'); } })} className={`flex size-5 shrink-0 items-center justify-center rounded-full border-2 transition ${task.status === 'completed' ? 'border-[#317e77] bg-[#317e77] text-white' : 'border-border hover:border-primary'}`}>{task.status === 'completed' && <Check size={12} />}</button><div className="min-w-0 flex-1"><div className={`text-sm font-semibold ${task.status === 'completed' ? 'text-muted-foreground line-through' : ''}`}>{task.title}</div><div className="mt-1 text-xs text-muted-foreground">{task.clientName || 'Sem cliente'} {task.propertyTitle ? `· ${task.propertyTitle}` : ''}</div></div><Status tone={task.priority === 'high' ? 'red' : task.priority === 'medium' ? 'warm' : 'neutral'}>{task.priority}</Status><div className="hidden w-20 text-right font-mono-ui text-[10px] text-muted-foreground sm:block">{shortDate(task.date)}<br />{task.time}</div></div>)}</div>}</Panel>{showAdd && <Modal title="Nova tarefa" onClose={() => setShowAdd(false)}><form onSubmit={submit} className="space-y-3">{[['title','O que precisa ser feito?','Retornar contato com cliente'],['clientName','Cliente','Ana Luiza'],['date','Data','2025-09-18'],['time','Horário','09:30']].map(([n,l,p]) => <label key={n} className="block"><span className="mb-1 block text-xs font-semibold">{l}</span><input required={n === 'title' || n === 'date'} name={n} placeholder={p} type={n === 'date' ? 'date' : n === 'time' ? 'time' : 'text'} className="h-10 w-full rounded-lg border border-border bg-muted/30 px-3 text-sm outline-none focus:border-primary" /></label>)}<label className="block"><span className="mb-1 block text-xs font-semibold">Prioridade</span><select name="priority" className="h-10 w-full rounded-lg border border-border bg-muted/30 px-3 text-sm"><option value="medium">Normal</option><option value="high">Alta</option><option value="low">Baixa</option></select></label><div className="flex justify-end gap-2 pt-3"><button type="button" onClick={() => setShowAdd(false)} className="rounded-lg px-4 py-2 text-sm text-muted-foreground">Cancelar</button><button data-testid="button-save-task" className="rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-primary-foreground">Criar tarefa</button></div></form></Modal>}</>; }

function Visits() { const [showAdd, setShowAdd] = useState(false); const { data, isLoading } = useListVisits(); const create = useCreateVisit(); const qc = useQueryClient(); const submit = (e: React.FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); create.mutate({ data: { clientName: String(f.get('clientName')), propertyTitle: String(f.get('propertyTitle')), date: String(f.get('date')), time: String(f.get('time')), location: String(f.get('location')) } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListVisitsQueryKey() }); setShowAdd(false); toast.success('Visita agendada.'); } }); }; return <><PageHeader title="Visitas" description="A agenda que transforma interesse em endereço." action={() => setShowAdd(true)} actionLabel="Agendar visita" /><div className="grid gap-5 xl:grid-cols-[1.15fr_.85fr]"><Panel><div className="flex items-center justify-between border-b border-border px-5 py-4"><div><h3 className="font-display text-lg font-semibold">Próximos encontros</h3><p className="text-xs text-muted-foreground">Sua agenda imobiliária</p></div><CalendarDays size={18} className="text-[#9b681d]" /></div>{isLoading ? <LoadingRows /> : !data?.length ? <Empty label="Nenhuma visita agendada." action={() => setShowAdd(true)} /> : <div className="divide-y divide-border">{data.map((visit) => <div key={visit.id} className="flex gap-4 px-5 py-5"><div className="w-12 shrink-0 text-center"><div className="font-mono-ui text-[10px] uppercase text-muted-foreground">{new Date(visit.date).toLocaleDateString('pt-BR', { month: 'short' }).replace('.', '')}</div><div className="font-display text-2xl font-semibold">{new Date(visit.date).getDate()}</div></div><div className="flex-1 border-l border-border pl-4"><div className="flex flex-wrap items-center justify-between gap-2"><div className="text-sm font-semibold">{visit.clientName}</div><Status tone={visit.status === 'confirmed' ? 'green' : 'warm'}>{visit.status}</Status></div><div className="mt-1 text-sm text-muted-foreground">{visit.propertyTitle}</div><div className="mt-3 flex items-center gap-3 text-xs text-muted-foreground"><span className="flex items-center gap-1"><Clock3 size={12} /> {visit.time}</span><span className="flex items-center gap-1"><Building2 size={12} /> {visit.location}</span></div></div></div>)}</div>}</Panel><Panel className="p-5"><div className="font-mono-ui text-[10px] uppercase tracking-[.13em] text-muted-foreground">Ritmo da semana</div><div className="mt-2 font-display text-3xl font-semibold">{data?.length ?? 0} <span className="text-base font-normal text-muted-foreground">visitas na agenda</span></div><div className="mt-6 flex h-32 items-end gap-2">{['seg','ter','qua','qui','sex','sáb'].map((d, i) => <div key={d} className="flex flex-1 flex-col items-center gap-2"><div className={`w-full rounded-t bg-${i === 2 ? 'accent' : 'muted'} transition`} style={{ height: `${[42, 64, 80, 50, 32, 18][i]}%`, backgroundColor: i === 2 ? 'hsl(var(--accent))' : 'hsl(var(--muted))' }} /><span className="font-mono-ui text-[9px] text-muted-foreground">{d}</span></div>)}</div></Panel></div>{showAdd && <Modal title="Agendar visita" onClose={() => setShowAdd(false)}><form onSubmit={submit} className="space-y-3">{[['clientName','Cliente','Ana Luiza'],['propertyTitle','Imóvel','Apartamento Bosque Alto'],['date','Data','2025-09-20'],['time','Horário','15:00'],['location','Local','Rua dos Pinheiros, 412']].map(([n,l,p]) => <label key={n} className="block"><span className="mb-1 block text-xs font-semibold">{l}</span><input required name={n} placeholder={p} type={n === 'date' ? 'date' : n === 'time' ? 'time' : 'text'} className="h-10 w-full rounded-lg border border-border bg-muted/30 px-3 text-sm outline-none focus:border-primary" /></label>)}<div className="flex justify-end gap-2 pt-3"><button type="button" onClick={() => setShowAdd(false)} className="rounded-lg px-4 py-2 text-sm text-muted-foreground">Cancelar</button><button data-testid="button-save-visit" className="rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-primary-foreground">Agendar</button></div></form></Modal>}</>; }

function Funnel() {
  const { data } = useListLeads();
  const update = useUpdateLead();
  const qc = useQueryClient();
  const stages = ['Novo Lead', 'Primeiro Contato', 'Qualificado', 'Imóvel Apresentado', 'Visita Agendada', 'Proposta', 'Negociação', 'Sem Resposta'];
  const move = (id: number, stage: string) => update.mutate({ id, data: { stage } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListLeadsQueryKey() }); toast.success('Etapa atualizada.'); } });
  return <><PageHeader title="Funil" description="Arraste cada oportunidade até o próximo movimento." /><div className="flex gap-3 overflow-x-auto pb-4">{stages.map((stage) => <div key={stage} className="w-[270px] shrink-0 rounded-xl border border-border bg-card p-3" onDragOver={(event) => event.preventDefault()} onDrop={(event) => { const id = Number(event.dataTransfer.getData('leadId')); if (id) move(id, stage); }}><div className="mb-3 flex items-center justify-between"><span className="font-mono-ui text-[10px] uppercase tracking-wider text-muted-foreground">{stage}</span><span className="rounded-full bg-muted px-2 py-0.5 font-mono-ui text-[10px]">{data?.items.filter((lead) => lead.stage === stage).length || 0}</span></div><div className="min-h-32 space-y-2">{data?.items.filter((lead) => lead.stage === stage).map((lead) => <div key={lead.id} draggable onDragStart={(event) => event.dataTransfer.setData('leadId', String(lead.id))} className="cursor-grab rounded-lg border border-border bg-background p-3 shadow-xs transition hover:-translate-y-0.5 hover:border-primary/50"><div className="text-sm font-semibold">{lead.name}</div><div className="mt-1 text-xs text-muted-foreground">{lead.interest} · {money(lead.budget)}</div><div className="mt-3 flex items-center justify-between"><Status tone={lead.temperature === 'Quente' ? 'warm' : 'neutral'}>{lead.temperature}</Status><span className="font-mono-ui text-[10px] text-muted-foreground">{lead.source}</span></div></div>)}</div></div>)}</div></>;
}

function Agenda() {
  const { data: visits } = useListVisits();
  const { data: tasks } = useListTasks({ filter: 'all' });
  const days = Array.from({ length: 7 }, (_, index) => new Date(Date.now() + index * 86400000).toISOString().slice(0, 10));
  return <><PageHeader title="Agenda" description="Visitas, tarefas e próximos contatos em uma única leitura." action={() => toast('Crie visitas e tarefas pelos módulos correspondentes.')} actionLabel="Novo evento" /><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">{days.map((day) => { const dayVisits = visits?.filter((visit) => visit.date === day) || []; const dayTasks = tasks?.filter((task) => task.date === day) || []; return <Panel key={day} className="min-h-44 p-4"><div className="flex items-center justify-between"><div><div className="font-mono-ui text-[10px] uppercase tracking-wider text-muted-foreground">{new Date(day).toLocaleDateString('pt-BR', { weekday: 'short' }).replace('.', '')}</div><div className="font-display text-2xl font-semibold">{new Date(day).getDate()}</div></div><CalendarDays size={16} className="text-muted-foreground" /></div><div className="mt-4 space-y-2">{dayVisits.map((visit) => <div key={`v-${visit.id}`} className="rounded-md bg-accent/25 p-2 text-xs"><span className="font-semibold">{visit.time}</span> · {visit.clientName}</div>)}{dayTasks.map((task) => <div key={`t-${task.id}`} className="rounded-md bg-muted p-2 text-xs"><span className="font-semibold">{task.time || '—'}</span> · {task.title}</div>)}{!dayVisits.length && !dayTasks.length && <div className="pt-2 text-xs text-muted-foreground">Sem eventos</div>}</div></Panel>; })}</div></>;
}

function Notifications() {
  const { data, isLoading } = useGetDashboard();
  const items = [...(data?.overdueTasks || []).map((task) => ({ title: 'Follow-up atrasado', description: task.title, tone: 'red' })), ...(data?.nextVisits || []).map((visit) => ({ title: 'Visita próxima', description: `${visit.clientName} · ${visit.propertyTitle}`, tone: 'warm' })), ...(data?.commissions || []).filter((commission) => commission.status !== 'Recebida').map((commission) => ({ title: 'Comissão pendente', description: `${commission.propertyTitle} · ${money(commission.net)}`, tone: 'green' }))];
  return <><PageHeader title="Notificações" description="Os sinais que merecem uma resposta antes de virarem problema." /><Panel>{isLoading ? <LoadingRows count={5} /> : items.length ? <div className="divide-y divide-border">{items.map((item, index) => <div key={`${item.title}-${index}`} className="flex items-start gap-3 px-5 py-4"><div className={`mt-1 rounded-full p-2 ${item.tone === 'red' ? 'bg-red-100 text-red-700' : item.tone === 'green' ? 'bg-emerald-100 text-emerald-700' : 'bg-accent/25 text-amber-800'}`}><Bell size={14} /></div><div><div className="text-sm font-semibold">{item.title}</div><div className="mt-1 text-xs text-muted-foreground">{item.description}</div></div><button onClick={() => toast.success('Notificação marcada como vista.')} className="ml-auto rounded-lg border border-border px-3 py-1.5 text-xs font-semibold">Marcar vista</button></div>)}</div> : <Empty label="Você está em dia. Nenhuma notificação nova." />}</Panel></>;
}

function TablePage({ kind }: { kind: 'proposals' | 'captures' | 'commissions' }) { const labels = { proposals: ['Propostas', 'Acompanhe cada negociação até a assinatura.'], captures: ['Captações', 'O inventário começa antes da placa.'], commissions: ['Comissões', 'Dinheiro previsto, recebido e a caminho.'] }[kind]; const proposals = useListProposals(); const captures = useListCaptures(); const commissions = useListCommissions(); const data: any[] = kind === 'proposals' ? proposals.data || [] : kind === 'captures' ? captures.data || [] : commissions.data || []; const loading = kind === 'proposals' ? proposals.isLoading : kind === 'captures' ? captures.isLoading : commissions.isLoading; const cols = kind === 'proposals' ? ['Cliente', 'Imóvel', 'Proposta', 'Status', 'Validade'] : kind === 'captures' ? ['Proprietário', 'Imóvel', 'Valor pedido', 'Etapa', 'Próximo contato'] : ['Cliente', 'Imóvel', 'Venda', 'Líquido', 'Status']; return <><PageHeader title={labels[0]} description={labels[1]} action={() => toast(kind === 'proposals' ? 'Crie propostas a partir de um lead qualificado.' : kind === 'captures' ? 'Use o formulário de captação em breve.' : 'Comissões são calculadas a partir das vendas fechadas.')} actionLabel={kind === 'proposals' ? 'Nova proposta' : kind === 'captures' ? 'Nova captação' : 'Registrar venda'} /><Panel>{loading ? <LoadingRows /> : !data.length ? <Empty label={`Nenhuma ${kind === 'proposals' ? 'proposta' : kind === 'captures' ? 'captação' : 'comissão'} por aqui ainda.`} /> : <div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left"><thead className="border-b border-border bg-muted/35 font-mono-ui text-[9px] uppercase tracking-wider text-muted-foreground"><tr>{cols.map((c) => <th className="px-5 py-3 font-medium" key={c}>{c}</th>)}<th /></tr></thead><tbody className="divide-y divide-border">{data.map((row) => <tr key={row.id} className="transition hover:bg-muted/35">{kind === 'proposals' && <><td className="px-5 py-4 text-sm font-semibold">{row.clientName}</td><td className="px-4 py-4 text-sm text-muted-foreground">{row.propertyTitle}</td><td className="px-4 py-4 font-display text-lg font-semibold">{money(row.proposedValue)}</td><td className="px-4 py-4"><Status tone={row.status === 'accepted' ? 'green' : 'warm'}>{row.status}</Status></td><td className="px-4 py-4 font-mono-ui text-xs text-muted-foreground">{shortDate(row.validUntil)}</td></>}{kind === 'captures' && <><td className="px-5 py-4 text-sm font-semibold">{row.ownerName}</td><td className="px-4 py-4 text-sm text-muted-foreground">{row.propertyTitle}</td><td className="px-4 py-4 font-display text-lg font-semibold">{money(row.askingValue)}</td><td className="px-4 py-4"><Status tone={row.stage === 'captado' ? 'green' : 'warm'}>{row.stage}</Status></td><td className="px-4 py-4 font-mono-ui text-xs text-muted-foreground">{shortDate(row.nextFollowUp)}</td></>}{kind === 'commissions' && <><td className="px-5 py-4 text-sm font-semibold">{row.clientName}</td><td className="px-4 py-4 text-sm text-muted-foreground">{row.propertyTitle}</td><td className="px-4 py-4 font-display text-lg font-semibold">{money(row.soldValue)}</td><td className="px-4 py-4 font-display text-lg font-semibold text-[#317e77]">{money(row.net)}</td><td className="px-4 py-4"><Status tone={row.status === 'received' ? 'green' : 'warm'}>{row.status}</Status></td></>}<td className="px-4 py-4"><button data-testid={`button-row-menu-${row.id}`} onClick={() => toast('Detalhes em breve.')} className="rounded p-1 text-muted-foreground hover:bg-muted"><MoreHorizontal size={16} /></button></td></tr>)}</tbody></table></div>}</Panel></>; }

function Reports() { const { data, isLoading } = useGetReports({ query: { queryKey: getGetReportsQueryKey() } }); const max = (arr: any[]) => Math.max(...arr.map((x) => x.value), 1); return <><PageHeader title="Relatórios" description="Leia o padrão por trás do seu ritmo comercial." action={() => toast('Relatório exportado em breve.')} actionLabel="Exportar relatório" />{isLoading ? <Panel><LoadingRows count={6} /></Panel> : <div className="grid gap-5 lg:grid-cols-2"><Panel className="p-5"><h3 className="font-display text-lg font-semibold">Origem dos leads</h3><p className="mt-1 text-xs text-muted-foreground">De onde vem a conversa</p><Bars data={data?.sources || []} color="accent" /></Panel><Panel className="p-5"><h3 className="font-display text-lg font-semibold">Bairros mais buscados</h3><p className="mt-1 text-xs text-muted-foreground">O mapa do desejo dos seus clientes</p><Bars data={data?.neighborhoods || []} color="teal" /></Panel><Panel className="p-5"><h3 className="font-display text-lg font-semibold">Visão do mês</h3><div className="mt-5 grid grid-cols-3 gap-3">{[['Visitas', data?.visits ?? 0], ['Propostas', data?.proposals ?? 0], ['Vendas', data?.sales ?? 0]].map(([l,v]) => <div key={String(l)} className="rounded-lg bg-muted/45 p-4"><div className="font-mono-ui text-[9px] uppercase tracking-wider text-muted-foreground">{l}</div><div className="mt-2 font-display text-3xl font-semibold">{v}</div></div>)}</div><div className="mt-5 h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-accent" style={{ width: `${Math.min(100, Number(data?.sales || 0) * 14)}%` }} /></div><div className="mt-2 flex justify-between font-mono-ui text-[9px] text-muted-foreground"><span>ritmo de vendas</span><span>meta anual</span></div></Panel><Panel className="p-5"><h3 className="font-display text-lg font-semibold">Tipos de imóvel</h3><Bars data={data?.propertyTypes || []} color="navy" /></Panel></div>}{void max}</>; }
function Bars({ data, color }: { data: { label: string; value: number }[]; color: 'accent' | 'teal' | 'navy' }) { const max = Math.max(...data.map((x) => x.value), 1); const bg = color === 'accent' ? 'bg-accent' : color === 'teal' ? 'bg-[#317e77]' : 'bg-primary'; return <div className="mt-6 space-y-4">{data.length ? data.slice(0, 6).map((item) => <div key={item.label} className="flex items-center gap-3"><span className="w-24 truncate text-xs text-muted-foreground">{item.label}</span><div className="h-2 flex-1 overflow-hidden rounded-full bg-muted"><div className={`h-full rounded-full ${bg}`} style={{ width: `${(item.value / max) * 100}%` }} /></div><span className="w-7 text-right font-mono-ui text-xs">{item.value}</span></div>) : <Empty label="Dados suficientes aparecerão aqui em breve." />}</div>; }
function SettingsPage() { const { user } = useUser(); return <><PageHeader title="Configurações" description="Seu espaço, do seu jeito." /><div className="grid gap-5 lg:grid-cols-[1fr_360px]"><Panel className="p-6"><div className="flex items-center gap-4"><Avatar name={user?.firstName || 'Marina Barros'} tone="gold" /><div><h3 className="font-display text-xl font-semibold">{user?.fullName || 'Marina Barros'}</h3><p className="text-sm text-muted-foreground">{user?.primaryEmailAddress?.emailAddress || 'corretora@montra.com'}</p></div><button data-testid="button-edit-profile" onClick={() => toast('Edição de perfil em breve.')} className="ml-auto rounded-lg border border-border px-3 py-2 text-xs font-semibold">Editar perfil</button></div><div className="mt-8 space-y-5"><div className="border-b border-border pb-5"><h3 className="font-display text-lg font-semibold">Preferências</h3><p className="mt-1 text-xs text-muted-foreground">Como o montra deve trabalhar para você</p></div>{[['Notificações de follow-up','Receba um lembrete quando uma oportunidade pedir atenção.'],['Resumo semanal','Uma leitura curta do seu ritmo toda segunda-feira.'],['Atalhos de teclado','Navegue rápido pelo seu pipeline.']].map(([title, text], i) => <div key={title} className="flex items-center justify-between gap-4"><div><div className="text-sm font-semibold">{title}</div><div className="mt-1 text-xs text-muted-foreground">{text}</div></div><button data-testid={`button-toggle-setting-${i}`} onClick={(e) => { e.currentTarget.classList.toggle('bg-accent'); toast('Preferência atualizada.'); }} className={`relative h-6 w-11 rounded-full bg-muted transition`}><span className="absolute left-1 top-1 size-4 rounded-full bg-card shadow-sm transition" /></button></div>)}</div></Panel><Panel className="p-6"><div className="flex items-center gap-2"><div className="rounded-lg bg-muted p-2"><Command size={17} /></div><div><h3 className="font-display text-lg font-semibold">Integrações</h3><p className="text-xs text-muted-foreground">Conecte seu jeito de trabalhar</p></div></div><div className="mt-6 space-y-3">{['WhatsApp Business','Google Agenda','Portal de imóveis'].map((name) => <div key={name} className="flex items-center justify-between rounded-lg border border-border p-3"><div className="flex items-center gap-3"><div className="size-2 rounded-full bg-muted-foreground/40" /><span className="text-sm font-medium">{name}</span></div><button data-testid={`button-connect-${name.toLowerCase().replaceAll(' ','-')}`} onClick={() => toast(`${name}: integração em configuração.`)} className="text-xs font-semibold text-[#9b681d]">Conectar</button></div>)}</div></Panel></div></>; }

function AuthPage({ type }: { type: 'in' | 'up' }) { return <div className="flex min-h-[100dvh] items-center justify-center bg-[#eee9df] px-4 py-8"><div className="absolute left-6 top-6"><Link href="/" className="flex items-center gap-2"><div className="flex size-8 items-center justify-center rounded-lg bg-primary font-display font-bold text-accent">M</div><span className="font-display text-lg font-bold">montra</span></Link></div>{type === 'in' ? <SignIn routing="path" path={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} /> : <SignUp routing="path" path={`${basePath}/sign-up`} signInUrl={`${basePath}/sign-in`} />}</div>; }
function HomeRedirect() { return <><Show when="signed-in"><Redirect to="/dashboard" /></Show><Show when="signed-out"><HomePage /></Show></>; }
function Protected({ children }: { children: React.ReactNode }) { return <><Show when="signed-in"><Shell>{children}</Shell></Show><Show when="signed-out"><Redirect to="/" /></Show></>; }
function RoutedErrorBoundary({ children }: { children: React.ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }
function Router() { return <RoutedErrorBoundary><Switch><Route path="/" component={HomeRedirect} /><Route path="/sign-in/*?" component={() => <AuthPage type="in" />} /><Route path="/sign-up/*?" component={() => <AuthPage type="up" />} /><Route path="/dashboard">{() => <Protected><Dashboard /></Protected>}</Route><Route path="/leads/:id">{() => <Protected><LeadDetail /></Protected>}</Route><Route path="/leads">{() => <Protected><LeadList /></Protected>}</Route><Route path="/clients/:id">{() => <Protected><ClientDetail /></Protected>}</Route><Route path="/clients">{() => <Protected><ClientList /></Protected>}</Route><Route path="/funnel">{() => <Protected><Funnel /></Protected>}</Route><Route path="/properties/:id">{() => <Protected><PropertyDetail /></Protected>}</Route><Route path="/properties">{() => <Protected><PropertyList /></Protected>}</Route><Route path="/tasks">{() => <Protected><Tasks /></Protected>}</Route><Route path="/visits">{() => <Protected><Visits /></Protected>}</Route><Route path="/agenda">{() => <Protected><Agenda /></Protected>}</Route><Route path="/proposals">{() => <Protected><TablePage kind="proposals" /></Protected>}</Route><Route path="/captures">{() => <Protected><TablePage kind="captures" /></Protected>}</Route><Route path="/commissions">{() => <Protected><TablePage kind="commissions" /></Protected>}</Route><Route path="/reports">{() => <Protected><Reports /></Protected>}</Route><Route path="/notifications">{() => <Protected><Notifications /></Protected>}</Route><Route path="/settings">{() => <Protected><SettingsPage /></Protected>}</Route><Route component={NotFound} /></Switch></RoutedErrorBoundary>; }
function ClerkRoutes() { const [, setLocation] = useLocation(); return <ClerkProvider publishableKey={clerkPubKey} proxyUrl={clerkProxyUrl} appearance={clerkAppearance} signInUrl={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} localization={{ signIn: { start: { title: 'Bem-vinda de volta', subtitle: 'Entre para acompanhar seus negócios' } }, signUp: { start: { title: 'Crie seu espaço', subtitle: 'Seu próximo fechamento começa aqui' } } }} routerPush={(to) => setLocation(to.replace(basePath, '') || '/')} routerReplace={(to) => setLocation(to.replace(basePath, '') || '/')}><QueryClientProvider client={queryClient}><Router /></QueryClientProvider></ClerkProvider>; }
export default function App() { return <WouterRouter base={basePath}><ClerkRoutes /><Toaster position="bottom-right" toastOptions={{ className: 'font-sans' }} /></WouterRouter>; }